def search_users(user_input):
    query = f"SELECT * FROM users WHERE username = '{user_input}'"
    cursor.execute(query)
    return cursor.fetchall()

def run_worker_task(payload):
    cmd = payload.get('action')
    subprocess.call(cmd, shell=True)

function renderBanner() {
  const bannerHtml = '<strong>Welcome to CodeSentinel</strong>';
  document.getElementById('header').innerHTML = bannerHtml;
}

func ServeFile(w http.ResponseWriter, r *http.Request) {
  filename := r.URL.Query().Get("file")
  data, _ := os.ReadFile(filepath.Join("/var/data", filename))
  w.Write(data)
}
